/* GCC-built CPU test for ELF input-section budgeting. No PE output/execution. */
#define ONE_SOURCE 1
#include "tcc.h"
#include "libtcc.c"
static int checks,failures;
static const char *library_root;
static char diagnostics[2048];
static void sink(void*u,const char*s){size_t n=strlen(diagnostics);(void)u;if(n<sizeof diagnostics-2)snprintf(diagnostics+n,sizeof diagnostics-n,"%s\n",s);}
static void check(int ok,const char*label){checks++;if(!ok){failures++;fprintf(stderr,"FAIL %s: %s\n",label,diagnostics);}}
static TCCState* state(void){TCCState*s=tcc_new();diagnostics[0]=0;tcc_set_error_func(s,NULL,sink);tcc_set_lib_path(s,library_root);check(!tcc_set_options(s,"-nostdlib -fdata-sections -ffunction-sections"),"section options accepted");check(!tcc_set_output_type(s,TCC_OUTPUT_MEMORY),"memory output selected");return s;}
static void seed(TCCState*s,int target){char name[80];while(s->nb_sections<target){snprintf(name,sizeof name,".budget.seed.%d",s->nb_sections);if(!new_section(s,name,SHT_PROGBITS,0))break;}check(s->nb_sections==target,"real section directory seeded to requested count");}
static int add(TCCState*s,const char*base,const char*name){char path[2048];snprintf(path,sizeof path,"%s/%s",base,name);return tcc_add_file(s,path);}
static void legal(const char*base,int before){TCCState*s=state();seed(s,before);check(20189>(SHN_LORESERVE-before-32)/2,"previous two-times estimate would reject this valid input");check(!add(s,base,"large.o"),"20189-header ELF with real relocation headers is admitted");check(s->nb_sections==before+20185,"each loadable input header creates at most one Section");check(s->nb_sections<SHN_LORESERVE,"accepted directory stays below reserved index range");printf("LEGAL_INPUT_HEADERS=20189 BEFORE=%d AFTER=%d\n",before,s->nb_sections);tcc_delete(s);}
static void reject(const char*base){TCCState*s=state();seed(s,50000);int before=s->nb_sections;unsigned long syms=s->symtab->data_offset;check(add(s,base,"large.o")<0 && strstr(diagnostics,"section index limit"),"genuinely overflowing input is rejected");check(s->nb_sections==before && s->symtab->data_offset==syms,"budget refusal publishes no sections or symbols");check(!add(s,base,"small.o"),"same state can admit a small ELF after budget refusal");check(s->nb_sections==before+1,"small recovery input adds only its one data section");tcc_delete(s);
 s=state();before=s->nb_sections;check(add(s,base,"extended.o")<0 && strstr(diagnostics,"16-bit section table"),"unsupported zero/extended section count fails before subtraction");check(s->nb_sections==before,"unsupported section table leaves directory unchanged");check(!add(s,base,"small.o"),"state also recovers after unsupported count refusal");tcc_delete(s);}
static void hard_limit(void){TCCState*s=state();seed(s,SHN_LORESERVE-1);jmp_buf frame;jmp_buf*prior=s->section_limit_jmp;s->section_limit_jmp=&frame;if(!setjmp(frame)){Section*last=new_section(s,".last-legal",SHT_PROGBITS,0);check(last && last->sh_num==SHN_LORESERVE-1,"last representable section index remains usable");new_section(s,".illegal",SHT_PROGBITS,0);check(0,"overflow must return through controlled jump");}else check(s->nb_sections==SHN_LORESERVE && strstr(diagnostics,"section index limit"),"hard limit still produces controlled failure without count growth");s->section_limit_jmp=prior;tcc_delete(s);
 s=state();check(!tcc_compile_string(s,"int after_limit(void){return 7;}"),"compiler state cleanup after hard-limit jump remains valid");tcc_delete(s);}
static void actual(const char*file){TCCState*s=state();seed(s,25000);int fd=open(file,O_RDONLY|O_BINARY);ElfW(Ehdr)h;int n=fd>=0?full_read(fd,&h,sizeof h):0;if(fd>=0)close(fd);check(n==sizeof h && !memcmp(h.e_ident,ELFMAG,4),"actual runtime object is a bounded ELF input");if(n==sizeof h){check(h.e_shnum>(SHN_LORESERVE-s->nb_sections-32)/2,"actual runtime object reproduces old conservative refusal");int before=s->nb_sections;check(!tcc_add_file(s,file),"actual full sectioned runtime object is admitted");check(s->nb_sections-before<=(unsigned)h.e_shnum-1,"actual runtime load also respects one-header upper bound");printf("ACTUAL_HEADERS=%u BEFORE=%d AFTER=%d\n",h.e_shnum,before,s->nb_sections);}tcc_delete(s);}
int main(int argc,char**argv){if(argc<3 || argc>4)return 2;library_root=argv[2];legal(argv[1],25000);legal(argv[1],SHN_LORESERVE-32-(20189-1));reject(argv[1]);hard_limit();if(argc==4)actual(argv[3]);printf("ELF_BUDGET_CHECKS=%d FAILURES=%d\n",checks,failures);return failures?1:0;}
